-- ============================================================================
-- Migration 127 — RLS policy hardening (phases/db hardening addendum)
-- ============================================================================
-- kind: expand; reversible: true
-- repeatable: true
--
-- GENERATED by scripts/gen-rls-policies.mts. Do not edit by hand: run
-- `npm run gen:rls-policies` and commit the result. CI runs the same generator
-- with --check.
--
-- This file is REPEATABLE (see modules/db README, migration ledger): the generator rewrites it whenever a table
-- joins the registry, and every statement in it is idempotent (DROP POLICY IF EXISTS, then CREATE), so the runner
-- re-applies it when its checksum changes instead of failing closed.
--
-- Two changes that are only safe TOGETHER (measured in
-- docs/new-iot-platform/iot_telemetry/09-isolation-performance-benchmark.md):
--
--   1. app_current_tenant() / app_rls_bypass() become LANGUAGE sql ... BEGIN
--      ATOMIC. The body is bound to catalog OIDs when the function is created, so
--      a caller's search_path can no longer substitute current_setting() /
--      pg_has_role() (the plpgsql bodies resolved them at call time: a role able to
--      create a schema could turn the policy into a read-anything primitive). They
--      are also inlinable, so the planner sees through them.
--   2. Every tenant table gets the policy PAIR
--        tenant_isolation     USING ("tenantId" = (SELECT app_current_tenant()))
--        tenant_admin_bypass  TO app_admin USING ((SELECT app_rls_bypass()))
--      in place of the single `app_rls_bypass() OR "tenantId" = app_current_tenant()`.
--      The (SELECT ...) form is an InitPlan: one evaluation per statement instead
--      of per row, and a statement with no tenant context is a One-Time Filter
--      (no scan at all).
--      *** Item 1 WITHOUT item 2 is a measured 2000 ms regression: an inlined OR
--      *** policy flips plans to a BitmapAnd over the whole tenant index. Never
--      *** apply the functions of this file without the policies of this file.
--
-- Semantics, role by role (the effective row filter is unchanged):
--   * runtime role (not an app_admin member): tenant match only. Before: the
--     bypass half was always false for it; now the bypass policy does not apply.
--   * app_admin member: bypass OR tenant match. Unchanged.
--   * nullable "tenantId" (system rows): NULL = tenant is NULL, so the row is
--     invisible to tenant sessions and visible with bypass. Unchanged.
--   * malformed / empty / missing app.current_tenant: NULL, no rows, no error.
--     CHANGED (tighter): only canonical 8-4-4-4-12 uuid text counts as a tenant;
--     the old function also accepted {braced} and dash-less forms.
--   * a NOINHERIT member of app_admin: policies `TO app_admin` apply to roles
--     that INHERIT the privileges of app_admin, whereas pg_has_role(.., 'member')
--     ignores NOINHERIT. Such a login loses the bypass. CHANGED (tighter). The
--     logins this repository creates (`IN ROLE app_admin`) inherit.
--
-- Scope: the 523 tables listed below (the generator's registry scan) PLUS every
-- table in the current schema that still carries a 'tenant_isolation', 'tenant_self' policy in
-- the old single-policy shape - rollup / watermark tables created at deploy time are not
-- entities. The tenant column of those is read from the existing policy.
-- A tenant_isolation policy in a shape this file does not recognise is left alone
-- and reported with a WARNING; the final assertion fails the migration if any
-- policy still evaluates the bypass function inside an OR.
--
-- Idempotent and transactional: the deploy runner wraps the file in one
-- transaction (use `psql -1` when applying by hand), so a reader never sees a
-- table without its policies. It takes an ACCESS EXCLUSIVE lock per table until
-- COMMIT; lock_timeout below makes it fail (and roll back) instead of queueing
-- behind a long transaction. FORCE is not touched: enforcement state stays whatever
-- it was (migrations/manual/rls-force-{enable,disable}.sql).
-- ============================================================================

SET LOCAL lock_timeout = '60s';
-- DROP POLICY IF EXISTS is chatty (one NOTICE per absent policy, ~1000 lines); the summary below is re-enabled.
SET LOCAL client_min_messages = warning;

-- The bypass policy is `TO app_admin`; 122 creates the role, this makes the file
-- safe to apply on its own as well.
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_admin') THEN
    CREATE ROLE app_admin NOLOGIN;
  END IF;
END $$;

-- Canonical uuid text only; everything else (NULL, '', garbage, braces, dash-less) is NULL.
-- current_setting(..., true) never raises for a missing GUC and the cast is guarded by the
-- same regular expression, so no input can raise (fail closed, never an exception).
CREATE OR REPLACE FUNCTION app_current_tenant() RETURNS uuid
LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
  SELECT CASE
    WHEN current_setting('app.current_tenant', true)
         ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
    THEN current_setting('app.current_tenant', true)::uuid
  END;
END;

-- Both halves must hold: the session asked for bypass AND the connected role is a member of
-- app_admin (122). The GUC alone is a string anybody on the connection can set.
CREATE OR REPLACE FUNCTION app_rls_bypass() RETURNS boolean
LANGUAGE sql STABLE PARALLEL SAFE
BEGIN ATOMIC
  SELECT coalesce(current_setting('app.bypass_rls', true), 'off') = 'on'
         AND pg_has_role(current_user, 'app_admin', 'member');
END;

COMMENT ON FUNCTION app_current_tenant() IS
  'Tenant of this session: the canonical uuid text in app.current_tenant, else NULL. LANGUAGE sql BEGIN ATOMIC (OID-bound, search_path-proof, inlinable). Migration 127.';
COMMENT ON FUNCTION app_rls_bypass() IS
  'True only when the session opted into bypass (app.bypass_rls = on) AND the connected role is a member of app_admin. LANGUAGE sql BEGIN ATOMIC (OID-bound, search_path-proof, inlinable). Migration 127.';

