  stmts TEXT[] := ARRAY[
      $s$DROP POLICY IF EXISTS tenant_isolation ON %1$I$s$,
      $s$DROP POLICY IF EXISTS tenant_self ON %1$I$s$,
      $s$DROP POLICY IF EXISTS tenant_admin_bypass ON %1$I$s$,
      $s$CREATE POLICY tenant_isolation ON %1$I
       USING (%2$I = (SELECT app_current_tenant()))
       WITH CHECK (%2$I = (SELECT app_current_tenant()))$s$,
      $s$CREATE POLICY tenant_admin_bypass ON %1$I TO app_admin
       USING ((SELECT app_rls_bypass()))
       WITH CHECK ((SELECT app_rls_bypass()))$s$
  ];
  -- pg_get_expr() rendering of the pre-127 policy; group 1 is the tenant column.
  legacy_re CONSTANT TEXT := $re$^\(app_rls_bypass\(\) OR \("?([A-Za-z_][A-Za-z0-9_]*)"? = app_current_tenant\(\)\)\)\Z$re$;
  rec RECORD;
  stmt TEXT;
  done INT := 0;
  bad TEXT;
BEGIN
  FOR rec IN
    WITH listed AS (SELECT unnest(tables) AS tbl),
    existing AS (
      SELECT DISTINCT ON (c.relname) c.relname AS tbl,
             substring(pg_get_expr(p.polqual, p.polrelid) FROM legacy_re) AS col
        FROM pg_policy p JOIN pg_class c ON c.oid = p.polrelid
       WHERE c.relnamespace = current_schema()::regnamespace
         AND c.relkind IN ('r', 'p')
         AND p.polname IN ('tenant_isolation', 'tenant_self')
         AND substring(pg_get_expr(p.polqual, p.polrelid) FROM legacy_re) IS NOT NULL
       ORDER BY c.relname, p.polname
    )
    SELECT tbl, coalesce(e.col, 'tenantId') AS col
      FROM listed l FULL JOIN existing e USING (tbl)
     ORDER BY tbl
  LOOP
    -- An optional module this deployment never installed has no table here;
    -- skipping it is correct, failing the migration is not.
    CONTINUE WHEN to_regclass(format('%I.%I', current_schema(), rec.tbl)) IS NULL;
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', rec.tbl);
    FOREACH stmt IN ARRAY stmts LOOP
      EXECUTE format(stmt, rec.tbl, rec.col);
    END LOOP;
    done := done + 1;
  END LOOP;
  PERFORM set_config('client_min_messages', 'notice', true);
  RAISE NOTICE 'rls hardening: % tables on the tenant_isolation + tenant_admin_bypass pair', done;

  -- Anything still evaluating the bypass inside an OR is the shape this migration removes.
  SELECT string_agg(c.relname || '.' || p.polname, ', ') INTO bad
    FROM pg_policy p JOIN pg_class c ON c.oid = p.polrelid
   WHERE c.relnamespace = current_schema()::regnamespace
     AND p.polname IN ('tenant_isolation', 'tenant_self')
     AND pg_get_expr(p.polqual, p.polrelid) ~ 'app_rls_bypass';
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'rls hardening incomplete, old-shape policies remain: %', bad;
  END IF;

  -- A policy of this name in a shape nobody here wrote: not rewritten, but not silent either.
  FOR rec IN
    SELECT c.relname AS tbl, p.polname AS pol
      FROM pg_policy p JOIN pg_class c ON c.oid = p.polrelid
     WHERE c.relnamespace = current_schema()::regnamespace
       AND p.polname IN ('tenant_isolation', 'tenant_self')
       AND pg_get_expr(p.polqual, p.polrelid) !~ 'app_current_tenant'
  LOOP
    RAISE WARNING 'rls hardening: %.% has an unrecognised policy shape and was left as it is', rec.tbl, rec.pol;
  END LOOP;
END $$;
